import { Component, OnInit } from '@angular/core';
import {HomeService} from '../../home.service'
import {NavController} from '@ionic/angular'
import {Router} from '@angular/router'
import { AlertController } from '@ionic/angular';

@Component({
  selector: 'app-council',
  templateUrl: './council.page.html',
  styleUrls: ['./council.page.scss'],
})
export class CouncilPage implements OnInit {
  details=[];
  d={};
  constructor(private user:HomeService,private navCtrl:NavController,private router:Router,private alertCtrl:AlertController) {
    this.user.councilparty().subscribe(data =>{
      this.details=data as any;
    })
   }

  ngOnInit() {
  }
  btnClicked(d){
    localStorage.p='cc'
this.router.navigateByUrl('/emailform',d)
    }
    async logout(){
      const alert = await this.alertCtrl.create({
        header: 'Confirm!',
        message: '<strong>Do you want to Logout !</strong>',
        buttons: [
          {
            text: 'No',
            role: 'cancel',
            cssClass: 'secondary',
            handler: (blah) => {
              console.log('Confirm Cancel: blah');
            }
          }, {
            text: 'Yes',
            handler: () => {
              localStorage.clear();
      this.navCtrl.navigateBack('/login');
            }
          }
        ]
      });

      await alert.present();
    }
    btnclick(){
      this.navCtrl.navigateBack('/changepassword');
    }
}
